#!/usr/bin/env python3
"""Export bounded polish evidence only; never raw HAR, credentials, config or consent logs."""
from pathlib import Path
from urllib.parse import urlsplit
import hashlib,json,subprocess,shutil
root=Path('.local/polish-evidence');read=lambda p:json.loads(Path(p).read_text())
names=['ui-results','package-results','native-results','reinstall','settings','settings-validation','categories-php','viewer-php','provider-config','browser-results','categories-results','managerCategories-results','callbacks-results','maps-results','frontend-results','viewer-results','http-results','clientIdExample-results','localization-results','publicJson-results','liveGuard-results','providerParameters-results','pixels-results','gtm-results','config-php','public-registry-browser','public-registry-php','syntax','zip']
