for n,r in suites.items():assert not r.get('failed',0)and r.get('result')!='FAIL'and not any(x.get('result')=='FAIL'for x in r.get('results',[])),n
har_requests=0
for c in suites['browser-results']['results']:
 h=read('.local/evidence/'+c['name']+'.har')['log']['entries'];assert all(urlsplit(x['request']['url']).netloc=='127.0.0.1:8888'for x in h);har_requests+=len(h);c.pop('networkRequests',None);c['har_requests']=len(h)
assert sum(c['name'].startswith('providers-')for c in suites['browser-results']['results'])==256
before=read(root/'http-before.json');after=read(root/'http-after.json');network_before=read(root/'network-before.json');network_after=read(root/'network-after.json')
assert all(before['groups'][k]['banner_hashes']==after['groups'][k]['banner_hashes'] and after['groups'][k]['registry_bytes']<before['groups'][k]['registry_bytes']and before['groups'][k]['sql_min']==16 and after['groups'][k]['sql_max']==8 for k in before['groups'])
assert network_before['counts']==network_after['counts'];assert network_before['bundle']['assets/components/cookieconsentmanager/css/cookie-consent.min.css']==network_after['bundle']['assets/components/cookieconsentmanager/css/cookie-consent.min.css'];assert read(root/'php-before.json')['settings_read_twice']['queries_min']==10;assert read(root/'php-after.json')['settings_read_twice']['queries_max']==2
sig='cookieconsent-1.0.1';p=Path('.local/artifacts')/(sig+'.transport.zip');sha=hashlib.sha256(p.read_bytes()).hexdigest();assert sha=='cb239c590c9e1f4df42409e98c642b9b927e82934520748310830e4c9f24b3d4';assert p.read_bytes()==Path('.local/private/public-registry-b/'+p.name).read_bytes();assert sha==suites['zip']['sha256']
assert Path('.local/artifacts/cookieconsent-1.0.0.transport.zip').read_bytes()==Path('.local/release/cookieconsent-1.0.0.transport.zip').read_bytes()
assert hashlib.sha256(Path('.local/release/cookieconsent-1.0.0.transport.zip').read_bytes()).hexdigest()=='0ed4563a2e92cf5e40ba1c269dc0d39bd0acdb6b3fb12a86f734983ce2f4b04b'
assert subprocess.check_output(['git','rev-parse','main'],text=True).strip()==subprocess.check_output(['git','rev-parse','v1.0.0^{}'],text=True).strip()=='b6c4402a0d61c167ca9f677cc25dcc2c26e235c9'
review=Path('.local/review/public-registry');review.mkdir(parents=True,exist_ok=True)
for suffix in ['.transport.zip','.transport.zip.sha256','.inventory.json','.zip-inventory.json']:
 src=Path('.local/artifacts')/(sig+suffix);target=review/src.name
 if target.exists():assert target.read_bytes()==src.read_bytes(),'Do not overwrite a reviewed candidate'
 else:target.write_bytes(src.read_bytes());target.chmod(0o444)
r={'date':'2026-10-14','branch':'feature/modx2-commercial-polish-performance','base_commit':'b6c4402a0d61c167ca9f677cc25dcc2c26e235c9','implementation_commit':subprocess.check_output(['git','rev-parse','00b3c48'],text=True).strip(),'result':'GO FOR REVIEW; 1.0.1 is an unpublished local candidate','candidate_signature':sig,'candidate_sha256':sha,'tests':sum(x.get('tests',1)for x in suites.values()),'assertions':sum(x.get('assertions',0)for x in suites.values()),'failed':0,'network':{'existing_provider_combinations':256,'mock_har_requests':har_requests,'external_mock_requests':0,'before':network_before,'after':network_after},'performance':{'php_before':read(root/'php-before.json'),'php_after':read(root/'php-after.json'),'independent_http_before':before,'independent_http_after':after,'scope':'CMP fragment timing after MODX API bootstrap; independent PHP/HTTP requests and warm CLI runs. Same persisted data and identical localized banner HTML; public JSON measured separately. Local medians are not production promises.'},'suites':suites,'optimizations':['Batch five global settings in a native collection query, preserving key order/revision and fresh reads; no request or persistent cache.','File hash timings are negligible; hash_file/content cache busting retained.','Project technical public registry: display fields remain in PHP, v2 fingerprints unchanged; actual old consent upgrade verified. Audit event counts, SDK guards and banner design unchanged.'],'not_run':['Actual client hosting, database latency/concurrency/load, CDN/HTML/browser cache deployments or production deployment.','Firefox/WebKit, older native-dialog browsers, PHP 8.1/other versions, Windows/IIS/LiteSpeed and client Manager theme/plugins/static element customizations.','New real vendor/account delivery or genuine client JS-map backend/API key/tiles/geocode; controlled SDK/iframe regression only.','Full native late filesystem/DB failure injection, ENOSPC/power loss/races. Standard backup/restore limitations remain.','Publication of 1.0.1, main merge or any modification of v1.0.0/release assets: intentionally not performed.'],'findings':['Stock ExtJS prevents native Escape default; reproduced defaultPrevented=true/no cancel. Scoped dialog key handler fixes close without global events.','Native Tab may reach browser chrome; test verifies inert page background rather than imposing a custom keyboard trap.','Stock MODX Gravatar requests are blocked/excluded from component network assertions; the developer footer performs no automatic requests.'],'initial_runs':[{'result':'FAIL','scenario':'Native install of rebuilt local 1.0.1 signature with stale resolver OPcache','resolution':'Restarted disposable PHP; repeated actual 1.0.0-to-candidate native upgrade, exact consent/settings/log retention and full final regression passed. No atomic rollback claim.'}], 'evidence_scope':'Final minimal public registry and bundle: all recorded public/Manager/Viewer/HTTP suites rerun, native fresh/upgrade/reinstall/uninstall, genuine prior-release consent, PHP validation, syntax, reproducible native ZIP. Controlled SDKs; no real vendor delivery.'}
out=Path('docs/evidence');(out/'modx2-commercial-polish-results.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n')
for src,dest in [('services-ru-desktop.png','commercial-services-ru.png'),('guide-ru-mobile.png','commercial-guide-ru-mobile.png')]:shutil.copyfile(root/src,out/dest)
